create or replace function public.moreai_customer_knowledge_chunk_count(p_user_id uuid,p_document_id uuid)
returns bigint language plpgsql stable security invoker set search_path = ''
as $function$
declare v_count bigint;
begin
  if p_user_id is null or p_document_id is null then
    raise exception 'knowledge_chunk_count_arguments_invalid' using errcode='22023';
  end if;
  if not exists(select 1 from public.knowledge_documents d where d.id=p_document_id and d.owner_user_id=p_user_id) then
    raise exception 'knowledge_document_not_found_or_not_owned' using errcode='42501';
  end if;
  select count(*)::bigint into v_count from public.knowledge_chunks c
    where c.document_id=p_document_id and c.owner_user_id=p_user_id;
  return v_count;
end;
$function$;
revoke all on function public.moreai_customer_knowledge_chunk_count(uuid,uuid) from public,anon,authenticated;
grant execute on function public.moreai_customer_knowledge_chunk_count(uuid,uuid) to service_role;

-- Phase 09: persist approval decision and run-resume lifecycle events in the
-- same transaction as the approval/pause/run/checkpoint state transition.
-- Forward-only: replaces the existing RPC; does not mutate live data on creation.

create or replace function public.moreai_append_approval_lifecycle_event(
  p_run_id uuid, p_event_key text, p_event_type text, p_payload jsonb
) returns bigint
language plpgsql security definer set search_path='' as $$
declare
  v_existing public.outbox_events;
  v_sequence bigint;
  v_event_id uuid := gen_random_uuid();
  v_created_at timestamptz := now();
begin
  if p_run_id is null or p_event_key is null or char_length(p_event_key) not between 1 and 200
     or p_event_type is null or p_event_type !~ '^[a-z][a-z0-9_.-]{0,79}$'
     or jsonb_typeof(coalesce(p_payload,'{}'::jsonb)) <> 'object'
     or octet_length(coalesce(p_payload,'{}'::jsonb)::text) > 16384 then
    raise exception 'invalid_approval_lifecycle_event' using errcode='22023';
  end if;

  select * into v_existing
    from public.outbox_events
   where aggregate_type='agent_run' and aggregate_id=p_run_id and event_key=p_event_key;
  if found then
    if v_existing.payload->>'event_type' <> p_event_type
       or v_existing.payload->'event_payload' <> coalesce(p_payload,'{}'::jsonb) then
      raise exception 'approval_event_idempotency_conflict' using errcode='22023';
    end if;
    return v_existing.run_sequence;
  end if;

  insert into public.agent_run_event_counters(run_id,last_sequence)
  values(p_run_id,coalesce((select max(sequence) from public.agent_run_events where run_id=p_run_id),0))
  on conflict(run_id) do nothing;
  perform 1 from public.agent_run_event_counters where run_id=p_run_id for update;

  -- Re-check after taking the per-run counter lock to serialize concurrent
  -- decision requests and preserve the existing unique event-key invariant.
  select * into v_existing
    from public.outbox_events
   where aggregate_type='agent_run' and aggregate_id=p_run_id and event_key=p_event_key;
  if found then
    if v_existing.payload->>'event_type' <> p_event_type
       or v_existing.payload->'event_payload' <> coalesce(p_payload,'{}'::jsonb) then
      raise exception 'approval_event_idempotency_conflict' using errcode='22023';
    end if;
    return v_existing.run_sequence;
  end if;

  update public.agent_run_event_counters
     set last_sequence=last_sequence+1,updated_at=v_created_at
   where run_id=p_run_id returning last_sequence into v_sequence;

  insert into public.agent_run_events(id,run_id,event_type,sequence,payload,created_at)
  values(v_event_id,p_run_id,p_event_type,v_sequence,coalesce(p_payload,'{}'::jsonb),v_created_at);

  insert into public.outbox_events(
    id,aggregate_type,aggregate_id,event_type,payload,status,attempts,available_at,
    created_at,event_key,run_sequence
  ) values(
    v_event_id,'agent_run',p_run_id,'run.event',
    jsonb_build_object(
      'run_id',p_run_id,'event_id',v_event_id,'sequence',v_sequence,
      'event_type',p_event_type,'event_payload',coalesce(p_payload,'{}'::jsonb),
      'created_at',v_created_at
    ),
    'pending',0,v_created_at,v_created_at,p_event_key,v_sequence
  );
  return v_sequence;
end;
$$;

revoke all on function public.moreai_append_approval_lifecycle_event(uuid,text,text,jsonb)
  from public,anon,authenticated;
grant execute on function public.moreai_append_approval_lifecycle_event(uuid,text,text,jsonb)
  to service_role;

create or replace function public.moreai_decide_tool_approval(
  p_approval_id uuid,p_user_id uuid,p_decision text
) returns jsonb
language plpgsql security definer set search_path='public',pg_temp as $$
declare
  a public.agent_tool_approvals%rowtype;
  p public.agent_run_approval_pauses%rowtype;
  v_status text;
  v_run_status text;
  v_event_type text;
  v_event_payload jsonb;
begin
  if p_decision not in ('approved','denied') then
    raise exception 'invalid_approval_decision' using errcode='22023';
  end if;

  select * into a
    from public.agent_tool_approvals
   where id=p_approval_id and user_id=p_user_id
   for update;
  if not found then
    raise exception 'approval_not_found' using errcode='P0002';
  end if;

  select * into p
    from public.agent_run_approval_pauses
   where approval_id=p_approval_id
   for update;

  if not found then
    if a.status in ('approved','denied','expired','consumed') then
      v_status:=a.status;
    else
      update public.agent_tool_approvals
         set status=case when expires_at<=now() then 'expired' else p_decision end,
             decided_at=now(),decided_by=p_user_id
       where id=p_approval_id
       returning * into a;
      v_status:=a.status;
    end if;

    v_event_type:=case v_status
      when 'approved' then 'tool.approval_granted'
      when 'denied' then 'tool.approval_denied'
      when 'expired' then 'tool.approval_expired'
      else null end;
    if v_event_type is not null then
      v_event_payload:=jsonb_build_object(
        'approval_id',a.id,'tool',a.tool_key,'status',v_status,
        'arguments_hash',a.arguments_hash,'decided_at',a.decided_at
      );
      perform public.moreai_append_approval_lifecycle_event(
        a.run_id,'approval.decision:'||a.id::text||':'||v_status,
        v_event_type,v_event_payload
      );
    end if;

    return jsonb_build_object(
      'id',a.id,'run_id',a.run_id,'status',v_status,'resumed',false
    );
  end if;

  if a.status='pending' then
    v_status:=case when a.expires_at<=now() then 'expired' else p_decision end;
    update public.agent_tool_approvals
       set status=v_status,decided_at=now(),decided_by=p_user_id
     where id=a.id
     returning * into a;
    update public.agent_run_approval_pauses
       set status=v_status,decided_at=now()
     where id=p.id
     returning * into p;
  else
    v_status:=a.status;
    if p.status<>v_status then
      raise exception 'approval_pause_state_conflict' using errcode='40001';
    end if;
  end if;

  v_event_type:=case v_status
    when 'approved' then 'tool.approval_granted'
    when 'denied' then 'tool.approval_denied'
    when 'expired' then 'tool.approval_expired'
    else null end;
  if v_event_type is not null then
    v_event_payload:=jsonb_build_object(
      'approval_id',a.id,'tool',a.tool_key,'status',v_status,
      'arguments_hash',a.arguments_hash,'decided_at',a.decided_at,
      'checkpoint_key',p.checkpoint_key
    );
    perform public.moreai_append_approval_lifecycle_event(
      a.run_id,'approval.decision:'||a.id::text||':'||v_status,
      v_event_type,v_event_payload
    );
  end if;

  update public.agent_runs
     set status='queued',resume_pending=true,available_at=now(),updated_at=now()
   where id=p.run_id and status='waiting_approval'
   returning status into v_run_status;

  update public.agent_run_checkpoints
     set state=state||jsonb_build_object(
       'status',v_status,'decided_at',a.decided_at,'resume_pending',true
     ),created_at=now()
   where run_id=p.run_id and checkpoint_key=p.checkpoint_key;

  if coalesce(v_run_status='queued',false) then
    perform public.moreai_append_approval_lifecycle_event(
      p.run_id,'approval.resume_queued:'||a.id::text,
      'run.resume_queued',
      jsonb_build_object(
        'approval_id',a.id,'status',v_status,
        'checkpoint_key',p.checkpoint_key,'resume_pending',true
      )
    );
  end if;

  return jsonb_build_object(
    'id',a.id,'run_id',a.run_id,'status',v_status,
    'resumed',coalesce(v_run_status='queued',false)
  );
end;
$$;

revoke all on function public.moreai_decide_tool_approval(uuid,uuid,text)
  from public,anon,authenticated;
grant execute on function public.moreai_decide_tool_approval(uuid,uuid,text)
  to service_role;

-- Explicit, user-controlled Personal Memory. Conversation history remains a separate store.
create table if not exists public.moreai_customer_memory_preferences (
  user_id uuid primary key references auth.users(id) on delete cascade,
  enabled boolean not null default false,
  consent_version text not null,
  consented_at timestamptz,
  disabled_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint moreai_customer_memory_consent_version_nonempty check (length(consent_version) between 1 and 40)
);

create table if not exists public.moreai_customer_memories (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  title text not null,
  content text not null,
  source_type text not null default 'user_created',
  scope text not null default 'personal',
  expires_at timestamptz not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint moreai_customer_memory_title_length check (length(btrim(title)) between 1 and 120),
  constraint moreai_customer_memory_content_length check (length(btrim(content)) between 1 and 4000),
  constraint moreai_customer_memory_source_check check (source_type = 'user_created'),
  constraint moreai_customer_memory_scope_check check (scope = 'personal'),
  constraint moreai_customer_memory_expiry_check check (expires_at > created_at and expires_at <= updated_at + interval '366 days')
);

create index if not exists moreai_customer_memories_owner_expiry_idx
  on public.moreai_customer_memories (user_id, expires_at asc, updated_at desc);

alter table public.moreai_customer_memory_preferences enable row level security;
alter table public.moreai_customer_memories enable row level security;

drop policy if exists moreai_customer_memory_preferences_owner_all on public.moreai_customer_memory_preferences;
create policy moreai_customer_memory_preferences_owner_all
  on public.moreai_customer_memory_preferences for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

drop policy if exists moreai_customer_memories_owner_all on public.moreai_customer_memories;
create policy moreai_customer_memories_owner_all
  on public.moreai_customer_memories for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

revoke all on public.moreai_customer_memory_preferences from anon, authenticated;
revoke all on public.moreai_customer_memories from anon, authenticated;
grant all on public.moreai_customer_memory_preferences to service_role;
grant all on public.moreai_customer_memories to service_role;

create or replace function public.moreai_customer_set_memory_consent(
  p_user_id uuid, p_enabled boolean, p_consent_version text
) returns public.moreai_customer_memory_preferences
language plpgsql
security invoker
set search_path = ''
as $function$
declare v_row public.moreai_customer_memory_preferences%rowtype;
begin
  if p_user_id is null or p_enabled is null or p_consent_version is null
     or length(p_consent_version) not between 1 and 40 then
    raise exception 'memory_consent_arguments_invalid' using errcode = '22023';
  end if;
  insert into public.moreai_customer_memory_preferences (
    user_id, enabled, consent_version, consented_at, disabled_at, updated_at
  ) values (
    p_user_id, p_enabled, p_consent_version,
    case when p_enabled then now() else null end,
    case when p_enabled then null else now() end,
    now()
  )
  on conflict (user_id) do update set
    enabled = excluded.enabled,
    consent_version = excluded.consent_version,
    consented_at = case when excluded.enabled then now()
                        else public.moreai_customer_memory_preferences.consented_at end,
    disabled_at = case when excluded.enabled then null else now() end,
    updated_at = now()
  returning * into v_row;
  return v_row;
end;
$function$;

revoke all on function public.moreai_customer_set_memory_consent(uuid, boolean, text) from public, anon, authenticated;
grant execute on function public.moreai_customer_set_memory_consent(uuid, boolean, text) to service_role;


create or replace function public.moreai_customer_clear_personal_memory(p_user_id uuid)
returns bigint
language plpgsql
security invoker
set search_path = ''
as $function$
declare v_deleted bigint;
begin
  if p_user_id is null then
    raise exception 'memory_clear_user_required' using errcode = '22023';
  end if;
  update public.moreai_customer_memory_preferences
     set enabled = false, disabled_at = now(), updated_at = now()
   where user_id = p_user_id;
  delete from public.moreai_customer_memories where user_id = p_user_id;
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$function$;

revoke all on function public.moreai_customer_clear_personal_memory(uuid) from public, anon, authenticated;
grant execute on function public.moreai_customer_clear_personal_memory(uuid) to service_role;

-- Periodic retention purge for Personal Memory, independent of profile visits.
create or replace function public.moreai_worker_purge_expired_customer_memories()
returns bigint
language plpgsql
security invoker
set search_path = ''
as $function$
declare v_deleted bigint;
begin
  delete from public.moreai_customer_memories
   where expires_at <= now();
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$function$;

revoke all on function public.moreai_worker_purge_expired_customer_memories() from public, anon, authenticated;
grant execute on function public.moreai_worker_purge_expired_customer_memories() to service_role;

-- Phase 09: owner-scoped agent configuration and live worker capability registry.
create table if not exists public.moreai_customer_agent_configs (
    id uuid primary key default gen_random_uuid(),
    user_id uuid not null references auth.users(id) on delete cascade,
    runtime_key text not null check (runtime_key in ('manus', 'toolcall')),
    name text not null check (length(btrim(name)) between 2 and 80),
    description text not null default '' check (length(description) <= 500),
    system_prompt text not null default '' check (length(system_prompt) <= 12000),
    tool_keys text[] not null default '{}',
    enabled boolean not null default true,
    version integer not null default 1 check (version > 0),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);
create unique index if not exists moreai_customer_agent_configs_owner_name_uq
    on public.moreai_customer_agent_configs(user_id, lower(name));
create index if not exists moreai_customer_agent_configs_owner_updated_idx
    on public.moreai_customer_agent_configs(user_id, updated_at desc);
alter table public.moreai_customer_agent_configs enable row level security;
revoke all on public.moreai_customer_agent_configs from public, anon, authenticated;
grant select, insert, update, delete on public.moreai_customer_agent_configs to service_role;

create table if not exists public.moreai_worker_capability_snapshots (
    worker_id text primary key check (length(worker_id) between 8 and 128),
    runtime_keys text[] not null default '{}',
    capabilities jsonb not null default '{}'::jsonb,
    status text not null default 'healthy' check (status in ('healthy', 'degraded')),
    last_seen_at timestamptz not null default now(),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);
alter table public.moreai_worker_capability_snapshots enable row level security;
revoke all on public.moreai_worker_capability_snapshots from public, anon, authenticated;
grant select on public.moreai_worker_capability_snapshots to service_role;
grant insert, update on public.moreai_worker_capability_snapshots to service_role;

create or replace function public.moreai_worker_publish_capabilities(
    p_worker_id text,
    p_runtime_keys text[],
    p_capabilities jsonb,
    p_status text default 'healthy'
) returns jsonb
language plpgsql
security invoker
set search_path = ''
as $function$
declare v_row public.moreai_worker_capability_snapshots%rowtype;
begin
    if p_worker_id is null or length(p_worker_id) < 8 or length(p_worker_id) > 128
       or p_runtime_keys is null or p_capabilities is null
       or jsonb_typeof(p_capabilities) <> 'object'
       or p_status not in ('healthy', 'degraded') then
        raise exception 'invalid worker capability heartbeat' using errcode = '22023';
    end if;
    insert into public.moreai_worker_capability_snapshots(
        worker_id, runtime_keys, capabilities, status, last_seen_at, updated_at
    ) values (
        p_worker_id, p_runtime_keys, p_capabilities, p_status, now(), now()
    )
    on conflict (worker_id) do update set
        runtime_keys = excluded.runtime_keys,
        capabilities = excluded.capabilities,
        status = excluded.status,
        last_seen_at = now(),
        updated_at = now()
    returning * into v_row;
    return jsonb_build_object(
        'worker_id', v_row.worker_id,
        'runtime_keys', to_jsonb(v_row.runtime_keys),
        'status', v_row.status,
        'last_seen_at', v_row.last_seen_at
    );
end;
$function$;
revoke all on function public.moreai_worker_publish_capabilities(text, text[], jsonb, text) from public, anon, authenticated;
grant execute on function public.moreai_worker_publish_capabilities(text, text[], jsonb, text) to service_role;

create or replace function public.moreai_enqueue_chat_run_with_config(
    p_user_id uuid,
    p_conversation_id uuid,
    p_content text,
    p_agent_key text,
    p_idempotency_key text,
    p_agent_config_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
    v_config public.moreai_customer_agent_configs%rowtype;
begin
    if p_user_id is null or p_conversation_id is null
       or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
       or p_agent_key not in ('manus', 'toolcall')
       or p_idempotency_key is null or length(p_idempotency_key) < 12 or length(p_idempotency_key) > 128
       or p_agent_config_id is null then
        raise exception 'invalid configured chat enqueue request' using errcode = '22023';
    end if;
    select * into v_config
      from public.moreai_customer_agent_configs
     where id = p_agent_config_id and user_id = p_user_id and enabled = true
     for share;
    if not found or v_config.runtime_key <> p_agent_key then
        raise exception 'agent configuration not found or runtime mismatch' using errcode = '42501';
    end if;
    select * into v_conversation
      from public.conversations
     where id = p_conversation_id and user_id = p_user_id
     for update;
    if not found then
        raise exception 'conversation not found' using errcode = '42501';
    end if;
    select * into v_run from public.agent_runs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
        return jsonb_build_object('run', to_jsonb(v_run), 'message', null, 'replayed', true);
    end if;
    insert into public.conversation_messages(conversation_id, user_id, role, content, metadata)
    values (p_conversation_id, p_user_id, 'user', p_content, '{}'::jsonb)
    returning * into v_message;
    insert into public.agent_runs(
        user_id, workspace_id, conversation_id, status, idempotency_key, input, max_attempts
    ) values (
        p_user_id, v_conversation.workspace_id, p_conversation_id, 'queued',
        p_idempotency_key,
        jsonb_build_object(
            'prompt', p_content,
            'agent_key', p_agent_key,
            'agent_config', jsonb_build_object(
                'id', v_config.id,
                'runtime_key', v_config.runtime_key,
                'name', v_config.name,
                'system_prompt', v_config.system_prompt,
                'tool_keys', to_jsonb(v_config.tool_keys),
                'version', v_config.version
            ),
            'conversation_id', p_conversation_id,
            'message_id', v_message.id
        ),
        3
    ) returning * into v_run;
    update public.conversation_messages set run_id = v_run.id
     where id = v_message.id and user_id = p_user_id;
    v_message.run_id := v_run.id;
    return jsonb_build_object('run', to_jsonb(v_run), 'message', to_jsonb(v_message), 'replayed', false);
end;
$function$;
revoke all on function public.moreai_enqueue_chat_run_with_config(uuid, uuid, text, text, text, uuid) from public, anon, authenticated;
grant execute on function public.moreai_enqueue_chat_run_with_config(uuid, uuid, text, text, text, uuid) to service_role;
